// n8n Code node "Read request" (Run Once for All Items).
// Validates what the app sent and decides the ROUTE with plain rules (no AI).
// The "Router" box right after this one branches on the route, so the
// decisions are visible on the canvas.
//   silent          a person took over: the agent does not answer
//   agent_off       the agent is switched off in the panel
//   confirm_booking the visitor confirmed the booking form
//   goodbye         the visitor said goodbye: thanks + satisfaction survey
//   booking         the visitor asked to book (keywords, no AI needed)
//   ready_answer    a menu question with a ready, approved answer (no AI)
//   claude          free text: the only route that calls Claude
const b = ($input.first().json || {}).body || {};
const text = (v, max) => (typeof v === 'string' ? v.slice(0, max) : '');
const conversation_id = text(b.conversation_id, 64);

if (b.kind === 'booking_confirm') {
  const k = b.booking || {};
  if (!conversation_id || !k.slot || !k.name || !k.email || !['online', 'office'].includes(k.mode)) {
    throw new Error('invalid_input: booking fields missing');
  }
  return [{ json: { route: 'confirm_booking', conversation_id, booking: { slot: k.slot, mode: k.mode, name: text(k.name, 80), email: text(k.email, 120) } } }];
}

const message = text(b.message, 2000).trim();
if (!message) throw new Error('invalid_input: message is required');

const facts = Array.isArray(b.facts) ? b.facts : [];
const quick = Array.isArray(b.quick) ? b.quick : [];
const base = {
  conversation_id,
  message,
  instructions: text(b.instructions, 20000),
  facts,
  history: Array.isArray(b.history) ? b.history.slice(-10) : [],
  simulate_failure: b.simulate_failure === true,
};

let route = 'claude';
let ready = null;
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').trim();
const hit = quick.find((q) => norm(q.question) === norm(message));

if (b.status === 'human') route = 'silent';
else if (b.agent_enabled === false) route = 'agent_off';
else if (message.length <= 80 && /(^|[^\p{L}])(bye|goodbye|good bye|see you|see ya|tchau|adeus|até logo|ate logo|até mais|ate mais|adiós|adios|chau|hasta luego)(?=[^\p{L}]|$)/iu.test(message)) route = 'goodbye';
else if (/\b(book|booking|schedule|appointment|agendar|agendamento|marcar|reservar)\b/i.test(message)) route = 'booking';
else if (hit) {
  const fact = facts.find((f) => f.code === hit.code);
  if (fact) { route = 'ready_answer'; ready = { code: fact.code, content: fact.content }; }
}

return [{ json: { route, ready, ...base } }];

// n8n Code node "Goodbye + survey". The visitor said goodbye: thank them and
// open the satisfaction survey (1 to 5 stars + optional comment). Fixed text in
// the visitor's language, no AI. This is the only reply that does not end with
// a follow-up question.
const detectLang = (t) => {
  const s = String(t || '').toLowerCase();
  if (/(^|[^\p{L}])(quero|agendar|marcar|horário|horario|você|voce|obrigad[oa]|olá|ola|oi|tchau|consulta|gostaria|reunião|reuniao|abaixo|curso|quanto|posso|não|nao|sim|bom dia|boa tarde|boa noite|até|ate)(?=[^\p{L}]|$)/u.test(s)) return 'pt';
  if (/(^|[^\p{L}])(quiero|cita|hola|gracias|usted|puedo|adiós|adios|chau|hasta|cuánto|cuanto|necesito|buenos|buenas)(?=[^\p{L}]|$)/u.test(s)) return 'es';
  return 'en';
};
const lang = detectLang($input.first().json.message);
const reply = {
  en: 'Thank you so much for your time! Before you go, could you rate this conversation? It takes two seconds and helps us improve.',
  pt: 'Muito obrigado pela sua disposição! Antes de ir, pode avaliar esta conversa? Leva dois segundos e nos ajuda a melhorar.',
  es: '¡Muchas gracias por tu tiempo! Antes de irte, ¿puedes valorar esta conversación? Son dos segundos y nos ayuda a mejorar.',
}[lang];
return [{ json: { ok: true, route: 'goodbye', role: 'agent', reply, action: 'survey', intent: 'goodbye', knew: true } }];

// n8n Code node "Agent off message". Fixed text, no AI.
return [{ json: {
  ok: true, route: 'agent_off', role: 'system', needs_human: true, reason: 'Agent switched off',
  reply: 'Thanks for your message! Our online assistant is switched off right now, so a consultant will reply in this chat.',
} }];

// n8n Code node "Ready answer (no AI)". A menu question: reply with the approved
// fact exactly as written, then a fixed follow-up question (every answer ends
// with a question, so the conversation never stops dead). Instant and free.
const r = $input.first().json.ready;
return [{ json: {
  ok: true, route: 'ready_answer', role: 'agent', reply: `${r.content}\n\nIs there anything else you would like to know?`,
  fact_codes: [r.code], knew: true, needs_human: false, intent: 'question',
} }];

// n8n Code node "Offer times". After "Check free times" (the slots tool).
// The reply opens the booking card in the chat; the times shown come from the
// same tool, never from the AI. Fixed text, in the visitor's language.
const count = Number(($input.first().json || {}).count || 0);
const msg = String(($('Read request').first().json || {}).message || '').toLowerCase();
const detectLang = (t) => {
  const s = String(t || '').toLowerCase();
  if (/(^|[^\p{L}])(quero|agendar|marcar|horário|horario|você|voce|obrigad[oa]|olá|ola|oi|tchau|consulta|gostaria|reunião|reuniao|abaixo|curso|quanto|posso|não|nao|sim|bom dia|boa tarde|boa noite|até|ate)(?=[^\p{L}]|$)/u.test(s)) return 'pt';
  if (/(^|[^\p{L}])(quiero|cita|hola|gracias|usted|puedo|adiós|adios|chau|hasta|cuánto|cuanto|necesito|buenos|buenas)(?=[^\p{L}]|$)/u.test(s)) return 'es';
  return 'en';
};
const lang = detectLang(msg);

const TEXT = {
  en: { some: (n) => `Happy to help! There are ${n} free times in the next few days. Which one suits you best? Pick it below.`,
        none: 'There are no free times in the next few days, so a consultant will contact you to find one. Is there anything else I can help you with meanwhile?' },
  pt: { some: (n) => `Com prazer! Temos ${n} horários livres nos próximos dias. Qual fica melhor para você? É só escolher logo abaixo.`,
        none: 'Não há horários livres nos próximos dias, então um consultor vai entrar em contato para combinar. Posso ajudar com mais alguma coisa enquanto isso?' },
  es: { some: (n) => `¡Con gusto! Hay ${n} horarios libres en los próximos días. ¿Cuál te queda mejor? Elígelo aquí abajo.`,
        none: 'No hay horarios libres en los próximos días, así que un consultor te contactará para coordinar. ¿Puedo ayudarte con algo más mientras tanto?' },
}[lang];

if (count > 0) {
  return [{ json: { ok: true, route: 'booking_offer', role: 'agent', action: 'booking', intent: 'book_consultation', reply: TEXT.some(count) } }];
}
return [{ json: {
  ok: true, route: 'booking_offer', role: 'agent', intent: 'book_consultation', needs_human: true,
  reason: 'Wanted to book but no free times', reply: TEXT.none,
} }];

// n8n Code node "Booking result". After "Reserve slot" (the booking tool).
const r = $input.first().json || {};
if (r.ok) {
  return [{ json: {
    ok: true, route: 'booking_done', role: 'system',
    reply: `✅ Consultation requested for ${r.when} (Sydney time), ${r.where}. Reference ${r.ref}. ` +
           'A consultant will confirm by email. (This is a demo: no email is sent.) Is there anything else I can help you with?',
  } }];
}
const why = r.error === 'taken' || r.error === 'not_offered'
  ? 'Sorry, that time was just taken. Please pick another one.'
  : 'Sorry, we could not book that time. Please try again.';
return [{ json: { ok: true, route: 'booking_failed', role: null, reply: why } }];

// n8n Code node "Tool failure". A call to the app's tools failed.
const err = ($input.first().json || {}).error || {};
const detail = [err.message, err.description].filter((x) => typeof x === 'string' && x.trim()).join(' | ') || 'tool call failed';
return [{ json: { ok: false, error: 'tool_error', detail: detail.slice(0, 500) } }];

// n8n Code node "Build request" (Run Once for All Items).
//
// Only reached on the "claude" route. Receives the context the app sent (the
// agent never reads the database) and builds the Claude request. The reply format is FIXED here, in code, not in
// the editable instructions: editing the instructions in the panel can change
// the tone, never the contract the code checks afterwards.
const body = $input.first().json || {};

function text(v, max) {
  return typeof v === 'string' ? v.slice(0, max) : '';
}

const instructions = text(body.instructions, 20000);
const message = text(body.message, 2000).trim();
const facts = Array.isArray(body.facts) ? body.facts.slice(0, 200) : [];
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];

if (!instructions || !message) {
  throw new Error('invalid_input: instructions and message are required');
}

// Only facts the app marked as approved arrive here. Each one has a short code
// the model must cite; the next node checks every code against this list.
const approvedCodes = [];
const factLines = [];
for (const f of facts) {
  const code = text(f && f.code, 10);
  const content = text(f && f.content, 2000);
  if (!/^F\d{2,3}$/.test(code) || !content) continue;
  approvedCodes.push(code);
  factLines.push(`[${code}] ${text(f.title, 200)}: ${content}`);
}

const ROLE = { visitor: 'Visitor', agent: 'Assistant', staff: 'Harbour staff' };
const transcript = history
  .filter((m) => m && ROLE[m.role])
  .map((m) => `${ROLE[m.role]}: ${text(m.content, 2000)}`)
  .join('\n');

const rules = [
  '## Approved facts',
  'These are the ONLY things you may state as true about Harbour Study Abroad.',
  'Cite the code of every fact you use in fact_codes. If no fact answers the',
  'question, set knew to false and do not guess. Greetings and small talk need',
  'no fact.',
  '',
  factLines.join('\n') || '(no approved facts)',
].join('\n');

// The reply format, enforced by the API (structured outputs): the response is
// always valid JSON matching this schema. (Forced tool_choice is rejected by
// Claude Sonnet 5.5, so structured outputs is the supported way to get it.)
const replySchema = {
  type: 'object',
  properties: {
    reply: { type: 'string', description: 'The message shown to the visitor.' },
    knew: {
      type: 'boolean',
      description: 'true only if the approved facts answer the question (or it is a greeting). false if a person must answer.',
    },
    fact_codes: {
      type: 'array',
      items: { type: 'string' },
      description: 'Codes of the approved facts used, e.g. ["F07"]. Empty for greetings.',
    },
    needs_human: {
      type: 'boolean',
      description: 'true if a consultant must follow up (the facts do not answer, a quote, a complaint). Booking a consultation is NOT a reason.',
    },
    intent: {
      type: 'string',
      enum: ['question', 'book_consultation', 'talk_to_person', 'smalltalk'],
      description: 'book_consultation when the visitor wants to book, schedule or meet a consultant (the booking form then opens).',
    },
    reason: { type: 'string', description: 'Short internal note for the team when needs_human is true, otherwise empty.' },
  },
  required: ['reply', 'knew', 'fact_codes', 'needs_human', 'intent', 'reason'],
  additionalProperties: false,
};

const payload = {
  // "Simulate AI failure" in the panel sends a model that does not exist, so the
  // demo exercises the REAL error path of the workflow, not a fake one.
  model: body.simulate_failure === true ? 'harbour-simulated-failure' : 'claude-sonnet-5-5',
  max_tokens: 4096,  // room for adaptive thinking + the short JSON reply
  system: [
    { type: 'text', text: instructions, cache_control: { type: 'ephemeral' } },
    { type: 'text', text: rules, cache_control: { type: 'ephemeral' } },
  ],
  messages: [
    {
      role: 'user',
      content:
        (transcript ? `Conversation so far:\n${transcript}\n\n` : '') +
        `New message from the visitor:\n<visitor_message>\n${message}\n</visitor_message>`,
    },
  ],
  // low effort: short support replies from a fixed fact list, latency matters
  output_config: { effort: 'low', format: { type: 'json_schema', schema: replySchema } },
};

return [{ json: { payload, approved_codes: approvedCodes, message } }];

// n8n Code node "Check answer" (Run Once for All Items).
//
// The model's word is not trusted. This node checks the reply in code before it
// can reach the visitor:
//   1. the reply must come in the fixed format;
//   2. every fact it cites must be one of the approved facts sent in;
//   3. a deterministic guard blocks prices, money amounts and exact dates,
//      whatever the instructions say.
// Anything that fails becomes a hand-over to a person, never a guess.
const resp = $input.first().json || {};
const approved = new Set($('Build request').first().json.approved_codes || []);

// Structured output: the answer is the JSON in the text block.
let a = null;
try {
  const txt = (resp.content || []).filter((b) => b && b.type === 'text').map((b) => b.text).join('');
  a = JSON.parse(txt);
} catch (e) {
  a = null;
}
if (resp.stop_reason === 'refusal' || resp.stop_reason === 'max_tokens') a = null;

if (!a || typeof a.reply !== 'string' || !a.reply.trim() || typeof a.knew !== 'boolean') {
  return [{ json: { ok: false, error: 'invalid_output', detail: 'The model did not return the expected format.' } }];
}

const cited = Array.isArray(a.fact_codes) ? a.fact_codes.map(String) : [];
const unknown = cited.filter((c) => !approved.has(c));

function guard(t) {
  const rules = [
    [/(A\$|AU\$|NZ\$|US\$|R\$|\$|€|£)\s?\d/i, 'price'],
    [/\b(AUD|NZD|USD|BRL|EUR|GBP|CAD)\s?\d/i, 'price'],
    [/\d[\d,.]*\s?(dollars?|reais|euros?|pounds?)\b/i, 'price'],
    [/\b\d{1,3}\s?%\s?(off|discount|scholarship)/i, 'discount'],
    [/\b\d{1,2}\/\d{1,2}(\/\d{2,4})?\b/, 'exact date'],
  ];
  for (const [re, why] of rules) if (re.test(t)) return why;
  return null;
}

const blocked = guard(a.reply);
let reply = a.reply.trim();
let knew = a.knew;
let needsHuman = a.needs_human === true || a.knew === false;
let reason = typeof a.reason === 'string' ? a.reason.slice(0, 300) : '';
let guardrail = null;

if (unknown.length) {
  // cited something that is not an approved fact: do not send it
  guardrail = `unapproved fact cited: ${unknown.join(', ')}`;
  knew = false;
  needsHuman = true;
  reply = '';
} else if (blocked) {
  guardrail = blocked;
  needsHuman = true;
  reply = 'I can not share prices, discounts or exact dates here, so a consultant will send you the right details in this chat.';
}

// Every answer ends with a question, so the conversation never stops dead.
// The instructions ask for it; this makes sure of it, in the visitor's language.
const detectLang = (t) => {
  const s = String(t || '').toLowerCase();
  if (/(^|[^\p{L}])(quero|agendar|marcar|horário|horario|você|voce|obrigad[oa]|olá|ola|oi|tchau|consulta|gostaria|reunião|reuniao|abaixo|curso|quanto|posso|não|nao|sim|bom dia|boa tarde|boa noite|até|ate)(?=[^\p{L}]|$)/u.test(s)) return 'pt';
  if (/(^|[^\p{L}])(quiero|cita|hola|gracias|usted|puedo|adiós|adios|chau|hasta|cuánto|cuanto|necesito|buenos|buenas)(?=[^\p{L}]|$)/u.test(s)) return 'es';
  return 'en';
};
const FOLLOW_UP = {
  en: 'Is there anything else I can help you with?',
  pt: 'Posso ajudar com mais alguma coisa?',
  es: '¿Puedo ayudarte con algo más?',
};
let followUpAdded = false;
if (reply && !/[?？]\s*$/.test(reply)) {
  reply = `${reply}\n\n${FOLLOW_UP[detectLang(`${reply} ${$('Build request').first().json.message || ''}`)]}`;
  followUpAdded = true;
}

if (needsHuman && !reason) reason = guardrail ? `Guardrail: ${guardrail}` : 'The approved facts do not answer this question.';

return [{
  json: {
    ok: true,
    route: 'claude',
    role: 'agent',
    reply,            // empty = the app uses the hand-over message from settings
    knew,
    fact_codes: unknown.length ? [] : cited,
    needs_human: needsHuman,
    intent: ['question', 'book_consultation', 'talk_to_person', 'smalltalk'].includes(a.intent) ? a.intent : 'question',
    reason,
    guardrail,
    follow_up_added: followUpAdded,
    usage: resp.usage || null,
  },
}];

// n8n Code node "Describe failure" (Run Once for All Items).
// The Claude call failed (bad key, no credit, timeout, invalid request...).
// The workflow still answers the app, with ok:false, so the app can send the
// fallback message to the visitor and raise the alert in the panel.
// n8n puts the generic text in error.message and the API's own explanation in
// error.description: keep both so the panel shows the real cause.
const j = $input.first().json || {};
const err = j.error || {};
const parts = [err.message, err.description].filter((x) => typeof x === 'string' && x.trim());
const detail = (parts.join(' | ') || JSON.stringify(err) || 'unknown error').slice(0, 500);
return [{ json: { ok: false, error: 'ai_error', detail } }];
